  "permissionIdle": ["Kliknij „Jedź prosto · 10 s”. Pi przygotuje kamerę, analizę i sterowanie.", "Click “Drive forward · 10 s”. Pi prepares the camera, analysis and control.", "„Geradeaus fahren · 10 s“ klicken. Pi bereitet Kamera, Analyse und Steuerung vor."],
  trialPlanShort: ["Jazda prosto · maks. 10 s", "Forward driving · max. 10 s", "Geradeausfahrt · max. 10 s"],
  trialSimpleHelp: ["Test przejmuje sterowanie na maksymalnie 10 s. Wolna droga: małe impulsy prosto. Przeszkoda: postój; świeże GO wznawia jazdę w tej samej próbie. STOP operatora lub utrata komunikacji kończy próbę.", "The trial takes control for at most 10 s. Clear path: small forward pulses. Obstacle: pause; fresh GO resumes the same trial. Operator STOP or loss of communication ends the trial.", "Der Versuch übernimmt höchstens 10 s. Freier Weg: kleine Vorwärtsimpulse. Hindernis: Pause; aktuelles GO setzt denselben Versuch fort. Bediener-STOP oder Kommunikationsverlust beendet ihn."],
  trialAccept: ["Potwierdzam strefę i hamowanie", "I confirm the zone and braking", "Ich bestätige Bereich und Bremsen"],
  "trialAcceptanceHelp": ["Po obejrzeniu świeżej analizy podłogi i przeszkody oraz ręcznej próbie hamowania potwierdź warunki dla obecnej kamery, strefy i prędkości. Zapis nie uruchamia ruchu. Potem kliknij „Jedź prosto · 10 s”.", "After viewing fresh floor and obstacle analysis and manually checking braking, confirm conditions for the current camera, zone and speed. Saving does not start movement. Then click “Drive forward · 10 s”.", "Nach aktueller Boden- und Hindernisanalyse sowie manueller Bremsprüfung Bedingungen für Kamera, Bereich und Geschwindigkeit bestätigen. Speichern startet keine Bewegung. Danach „Geradeaus fahren · 10 s“ klicken."],
  "trialAcceptanceSaved": ["Warunki próby zapisane na Pi. Aby jechać, kliknij „Jedź prosto · 10 s”.", "Trial conditions saved on Pi. To drive, click “Drive forward · 10 s”.", "Versuchsbedingungen auf Pi gespeichert. Zum Fahren „Geradeaus fahren · 10 s“ klicken."],
  analysisRunning: ["Analiza uruchomiona", "Analysis running", "Analyse läuft"],
  modeDriveUnavailableHelp: ["Model nie obsługuje próby jazdy. Opcja „Podgląd bez jazdy” pozwala oglądać analizę; strzałki służą sterowaniu ręcznemu po uzbrojeniu Pi.", "The model does not support a driving trial. “Preview without driving” shows analysis; the arrows provide manual control after Pi arming.", "Das Modell unterstützt keinen Fahrversuch. „Vorschau ohne Fahrt“ zeigt die Analyse; die Pfeile dienen nach Pi-Freigabe der manuellen Steuerung."],
  "vision.reason.analysis_not_current": ["Brak świeżej oceny. „Jedź prosto · 10 s” przygotowuje kamerę i analizę automatycznie.", "No fresh assessment. “Drive forward · 10 s” prepares camera and analysis automatically.", "Keine aktuelle Bewertung. „Geradeaus fahren · 10 s“ bereitet Kamera und Analyse automatisch vor."],
  "startObservation": ["Włącz podgląd i analizę bez jazdy", "Enable preview and analysis without driving", "Vorschau und Analyse ohne Fahrt einschalten"],
